def development_frame():
    return pd.DataFrame([(x,1) for x in SUSPICIOUS]+[(x,0) for x in LOWER_RISK],columns=["text","fraudulent"])
def load_dataset(path=None):
    candidate=Path(path) if path else DATA_DIR/"emscad.csv"
    if candidate.exists():
        df=pd.read_csv(candidate); tc=next((c for c in ["description","text","job_description"] if c in df),None); lc=next((c for c in ["fraudulent","is_fraud","label"] if c in df),None)
        if not tc or not lc: raise ValueError("CSV needs description/text and fraudulent/is_fraud/label columns.")
        df=df[[tc,lc]].rename(columns={tc:"text",lc:"fraudulent"}); df["text"]=df.text.fillna("").astype(str); df["fraudulent"]=pd.to_numeric(df.fraudulent,errors="coerce"); df=df.dropna(subset=["fraudulent"]); df["fraudulent"]=df.fraudulent.astype(int).clip(0,1); df=df[df.text.str.strip().ne("")].drop_duplicates("text").reset_index(drop=True)
        if df.fraudulent.nunique()!=2 or len(df)<10: raise ValueError("Dataset must contain at least 10 rows and both labels.")
        return df,{"kind":"real","source":candidate.name,"license_note":"User-supplied CSV; confirm license and provenance before reuse."}
    return development_frame(),{"kind":"synthetic_demo","source":"Hand-authored illustrative examples in src/data_loader.py","license_note":"Metrics are demonstration-only, not evidence of real-world performance."}
